public class InnerRouterOutputRouterOutputConfigurationFactory(Action<Humidifier.MediaConnect.RouterOutputTypes.RouterOutputConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.RouterOutputTypes.RouterOutputConfiguration>
{

    internal InnerRouterOutputMediaLiveInputRouterOutputConfigurationFactory MediaLiveInputFactory { get; set; }

    internal InnerRouterOutputMediaConnectFlowRouterOutputConfigurationFactory MediaConnectFlowFactory { get; set; }

    internal InnerRouterOutputSourceEndpointRouterOutputConfigurationFactory SourceEndpointFactory { get; set; }

    internal InnerRouterOutputStandardRouterOutputConfigurationFactory StandardFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterOutputTypes.RouterOutputConfiguration Create()
    {
        var routerOutputConfigurationResult = CreateRouterOutputConfiguration();
        factoryAction?.Invoke(routerOutputConfigurationResult);

        return routerOutputConfigurationResult;
    }

    private Humidifier.MediaConnect.RouterOutputTypes.RouterOutputConfiguration CreateRouterOutputConfiguration()
    {
        var routerOutputConfigurationResult = new Humidifier.MediaConnect.RouterOutputTypes.RouterOutputConfiguration();

        return routerOutputConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterOutputTypes.RouterOutputConfiguration result)
    {
        base.CreateChildren(result);

        result.MediaLiveInput ??= MediaLiveInputFactory?.Build();
        result.MediaConnectFlow ??= MediaConnectFlowFactory?.Build();
        result.SourceEndpoint ??= SourceEndpointFactory?.Build();
        result.Standard ??= StandardFactory?.Build();
    }

} // End Of Class

